CriteriaBuilder cb = session.getCriteriaBuilder();
CriteriaQuery<Car> query = cb.createQuery(Car.class);
Root<Car> root = query.from(Car.class);
query.select(root);
List<Car> all = session.createQuery(query).getResultList();

Predicate byBrand = cb.equal(root.get("brand"), "Toyota");
Predicate byPrice = cb.lt(root.get("price"), 100000.0);
query.select(root).where(cb.and(byBrand, byPrice));

Predicate brandA = cb.equal(root.get("brand"), "Toyota");
Predicate brandB = cb.equal(root.get("brand"), "Honda");
query.select(root).where(cb.or(brandA, brandB));

// HQL: 1 linia - "from Car c where c.brand = :brand and c.price < :price"
// Criteria API: 5+ linii (cb, query, root, 2 predykaty, where)
// HQL jest zwiezlejszy dla STATYCZNEGO ksztaltu zapytania

static List<Car> searchCars(Session s, String brand, Double maxPrice) {
    CriteriaBuilder cb = s.getCriteriaBuilder();
    CriteriaQuery<Car> q = cb.createQuery(Car.class);
    Root<Car> r = q.from(Car.class);
    List<Predicate> preds = new ArrayList<>();
    if (brand != null) preds.add(cb.equal(r.get("brand"), brand));
    if (maxPrice != null) preds.add(cb.le(r.get("price"), maxPrice));
    q.select(r).where(cb.and(preds.toArray(new Predicate[0])));
    return s.createQuery(q).getResultList();
}

